VALUES ('wei-wen', '斯', ARRAY[]::text[], '姬', '魏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '尊师重道，任用李悝、吴起改革，灭中山。魏国率先强盛，为战国初霸，国势巅峰，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏文侯"}]'::jsonb, '文侯', NULL, '魏文侯')
