VALUES ('wei-r1', '击', ARRAY[]::text[], '姬', '魏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '文侯之子，武侯。吴起奔楚，秦攻韩赵而未全力救，国势有损，霸业渐衰，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏武侯"}]'::jsonb, '武侯', NULL, '魏武侯')
