VALUES ('wei-r2', '罃', ARRAY[]::text[], '姬', '魏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '惠成王，迁都大梁。桂陵、马陵惨败，又遭秦齐夹击，魏国由盛转衰，无力争霸，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏惠成王"}]'::jsonb, '惠成王', NULL, '魏惠成王')
