VALUES ('wei-r3', '嗣', ARRAY[]::text[], '姬', '魏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '襄王，在位二十二年。魏国已非战国强国，无力争霸，国势转衰，割地求和，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏襄王"}]'::jsonb, '襄王', NULL, '魏襄王')
