VALUES ('wei-r4', '遫', ARRAY[]::text[], '姬', '魏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '昭王，在位十八年。秦国屡攻魏国，割地求和，国势日衰，濒临灭亡，事迹载于《史记》相关记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏昭王"}]'::jsonb, '昭王', NULL, '魏昭王')
