VALUES ('wei-r5', '圉', ARRAY[]::text[], '姬', '魏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '安僖王，在位三十三年。魏国沦为秦国附庸，割地求和，国势危急，濒临灭亡，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏安僖王"}]'::jsonb, '安僖王', NULL, '魏安僖王')
