VALUES ('wei-r6', '午', ARRAY[]::text[], '姬', '魏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '景湣王，在位十四年。秦国攻魏取地，魏国奄奄一息，濒临灭亡，无力抵抗，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏景湣王"}]'::jsonb, '景湣王', NULL, '魏景湣王')
