VALUES ('wei-r7', '假', ARRAY[]::text[], '姬', '魏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '魏国末代君主。前225年秦灭魏，国亡，魏国历史终结，姬姓魏国不复存在，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/假"}]'::jsonb, NULL, NULL, '假')
