VALUES ('wu-qi', '吴起', ARRAY[]::text[], NULL, NULL, -440, 1, NULL, 'year', -381, 1, NULL, 'year', ARRAY['军事家','政治家'], '战国初期军事家、政治家，先后仕鲁、魏、楚。任魏西河守时治军拓地，入楚后任令尹，推行变法、整顿贵族与官制；楚悼王死后遭旧贵族杀害。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/吴起"}]'::jsonb, NULL, NULL, NULL)
